SELECT CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(rating) AS total_rating, COUNT(*) AS cnt, SUM(SUM(rating)) OVER (ORDER BY CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END) AS cumulative_rating FROM suppliers WHERE LENGTH(supplier_name) >= 14 GROUP BY CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END ORDER BY cumulative_rating DESC, rating_bucket LIMIT 3;
